import{d as p,C as s,o as g,c as d,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第三十九章","description":"《正易心法》第三十九章——一变为七，七变为九：引《冲虚经》「易变而为一，一变而为七，七变而为九，九复变而为一」，落到八宫卦「七变归魂、本宫之气革」的卦变周期，是第三十六章悬案的解答。","frontmatter":{"title":"正易心法·第三十九章","description":"《正易心法》第三十九章——一变为七，七变为九：引《冲虚经》「易变而为一，一变而为七，七变而为九，九复变而为一」，落到八宫卦「七变归魂、本宫之气革」的卦变周期，是第三十六章悬案的解答。","category":"guide","aliases":["正易心法第三十九章","一变为七七变为九","归魂与复变"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-39.md","filePath":"yijing/zheng-yi-xin-fa/chapter-39.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-39.md"},x=p({...c,setup(u){const i=[{id:"z39-01",label:"一、一变为七",showLabel:!0,sentences:[["一变为七，七变为九。即是",{text:"卦妄",glossary:"guawang"},"，宜究其实。"]],note:["一变为七、七变为九——这正是卦变的道理，应当追究其真实含义。（**本章解开了第三十六章留下的悬案**：第三十六章说「一变为七，七变为九。此之谓也」，**未给出出处**；本章引《冲虚经》，**原来那是《列子》的语言，不是麻衣自己的数字推演。**）"]},{id:"z39-02",label:"二、冲虚经之引",showLabel:!0,sentences:[["《",{text:"冲虚经",glossary:"chongxujing"},"》曰：《易》",{text:"无形埒",glossary:"wuxinglie"},"。易变而为一，一变而为七，七变而为九。九者，",{text:"究",glossary:"jiu"},"也，复变而为一。"]],note:["《冲虚经》（《列子》）说：《易》无形埒（没有形体的边界）。易变化而产生一，一变化而到达七，七变化而到达九。九，是穷尽之意，然后再变化回到一。（**《列子·天瑞》的宇宙生成序列**：无形之易 → 一 → 七 → 九（究）→ 复变为一。**这是宇宙从无到有、从有到极、从极返本的大循环。** 麻衣的贡献是：**把这个宇宙论模型，对应到八宫卦的变化次数（1→7→9→1）。**）"]},{id:"z39-03",label:"三、归魂与复变",showLabel:!0,sentences:[["盖卦爻自一变、二变、三变、四变、五变、六变、至七变，谓之",{text:"归魂",glossary:"guihun"},"，而",{text:"本宫之气革",glossary:"bengongZhiqiGe"},"矣。更二变而极于九，遂复变为一而",{text:"返本",glossary:"fanben"},"也。"]],note:["这是因为：卦爻从第一变、第二变、第三变、第四变、第五变、第六变，到第七变，称为「归魂」，此时本宫的气已经改变了；再经过两变而到达极点（第九变），于是再次变化回到一，返回根本。（**这是把《列子》的宇宙周期落到八宫卦上**：一（本卦）→ 七（归魂）→ 更二变极于九 → 复变为一。**「本宫之气革矣」是本章最耐人寻味的一句**：归魂听着像「回家」，**但回来的已不是原来那个**——**变化因此不是简单循环，而是螺旋。**）"]},{id:"z39-04",label:"四、溺空泛说",showLabel:!0,sentences:[["学者不悟经意",{text:"溺空泛说",glossary:"nikongFanshuo"},"，失之甚矣。"]],note:["学者不能领悟经典的真意，沉溺于空洞泛泛的说法，错得太厉害了。（**「失之甚矣」与第十三章「所失益甚矣」、第二十三章「失之远矣」同类**——都是麻衣对「空泛」的重话。**他的标准始终一致：任何概念都要有落处，没有落处的说法就是「空泛说」。**）"]}],o=[{id:"guawang",term:"卦妄",pinyin:"guà wàng",meaning:"卦变的道理。此处「妄」当读作「变」或「妄」之实义——即当究卦变的真实。"},{id:"chongxujing",term:"冲虚经",pinyin:"chōng xū jīng",meaning:"《列子》的道教尊称。唐代封《列子》为《冲虚真经》。"},{id:"wuxinglie",term:"无形埒",pinyin:"wú xíng liè",meaning:"没有形体的边界。埒＝界墙。《列子》语，指易的无形无界。"},{id:"jiu",term:"究",pinyin:"jiū",meaning:"穷尽、到头。九是极数，变化到了尽头，故「九者，究也」。"},{id:"guihun",term:"归魂",pinyin:"guī hún",meaning:"八宫卦第七变的名称：游魂卦再变，回归本宫。"},{id:"bengongZhiqiGe",term:"本宫之气革",pinyin:"běn gōng zhī qì gé",meaning:"本宫的气已经改变。革＝变革。七变后本宫气质已变——**回来的，已不是原来的那个**。"},{id:"fanben",term:"返本",pinyin:"fǎn běn",meaning:"返回根本。九变之后复归为一，循环完成。"},{id:"nikongFanshuo",term:"溺空泛说",pinyin:"nì kōng fàn shuō",meaning:"沉溺于空洞泛泛的说法。麻衣批评不究实义的学者。"}];return(b,n)=>{const r=s("DaoTextReading"),l=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t("",22)),e(r,{colophon:"一变为七 · 七变为九 · 七变归魂 · 复变返本",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第三十九章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入。原文「即是卦妄」之「妄」当读作实义（卦变之实），此处随底本，不作径改。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"冲虚经",pinyin:["chōng","xū"],meaning:"《列子》的道教尊称。本章所引「易变而为一，一变而为七，七变而为九」即出其中。"},{term:"无形埒",pinyin:["wú","xíng"],meaning:"没有形体的边界。「埒」是界墙——易无形界，故能为一切之始。"},{term:"一变为七七变为九",pinyin:["yī","biàn"],meaning:"第三十六章留下的悬案，本章给出出处：引自《列子·天瑞》。"},{term:"七变归魂",pinyin:["guī","hún"],meaning:"八宫卦第七变为归魂——魂归本宫，但「本宫之气革矣」，回来的已不是原来的那个。"},{term:"复变为一",pinyin:["fù","biàn"],meaning:"九变之后复归为一，返本还原，一个完整的变化周期结束。"}]}),n[3]||(n[3]=t("",22))])}}});export{y as __pageData,x as default};
